<% heading = @quiz.persisted? ? "Settings" : "New quiz" %>
<% content_for :title, heading %>
<nav class="breadcrumbs"><%= @quiz.persisted? ? link_to("← #{@quiz.title}", moderate_quiz_path(@quiz)) : link_to("← All quizzes", moderate_root_path) %></nav>
<div class="page-head"><h1><%= heading %></h1></div>
<%= form_with model: [:moderate, @quiz], class: "card" do |form| %>
  <div class="field">
    <%= form.label :title, "Title" %>
    <%= form.text_field :title, required: true, class: "input" %>
  </div>
  <%= render "shared/errors", record: @quiz %>
  <div class="buttons">
    <%= form.submit "Save quiz", class: "btn btn--pink" %>
    <%= link_to "Cancel", @quiz.persisted? ? moderate_quiz_path(@quiz) : moderate_root_path, class: "btn btn--ghost" %>
  </div>
<% end %>
<% if @quiz.persisted? %>
  <%= button_to "Delete quiz", moderate_quiz_path(@quiz), method: :delete, class: "btn btn--danger", form: { data: { confirm: "Delete this quiz and all of its questions?" } } %>
<% end %>
----app/views/moderate/quizzes/index.html.erb
<% content_for :title, "Quizzes" %>
<div class="page-head">
  <h1>Quizzes</h1>
  <%= link_to "New quiz", new_moderate_quiz_path, class: "btn btn--pink" %>
</div>
<% if @quizzes.any? %>
  <ul class="quiz-list">
    <% @quizzes.each do |quiz| %>
      <li class="card quiz-tile">
        <h2><%= link_to quiz.title, moderate_quiz_path(quiz) %></h2>
        <div class="meta"><%= pluralize(@question_counts.fetch(quiz.id, 0), "question") %></div>
      </li>
    <% end %>
  </ul>
<% else %>
  <p class="empty">No quizzes yet. Create a quiz to get started.</p>
<% end %>
----app/views/moderate/quizzes/show.html.erb
<% content_for :title, @quiz.title %>
<nav class="breadcrumbs"><%= link_to "← All quizzes", moderate_root_path %></nav>
<div class="page-head">
  <div>
    <h1><%= @quiz.title %></h1>
    <div class="meta mt-2"><%= @questions.count(&:active?) %> of <%= pluralize(@questions.size, "question") %> active · <%= link_to "Settings", edit_moderate_quiz_path(@quiz) %></div>
  </div>
  <%= link_to "Preview", moderate_quiz_preview_path(@quiz), class: "btn btn--ghost" %>
</div>
<section class="section mt-0" aria-labelledby="questions-title">
  <div class="section-head">
    <h2 id="questions-title">Questions</h2>
    <%= link_to "Add question", new_moderate_quiz_question_path(@quiz), class: "btn" %>
  </div>
  <% if @questions.empty? %>
    <p class="empty">No questions yet. Add the first question to your quiz.</p>
  <% else %>
    <ol class="question-list">
      <% active_number = 0 %>
      <% @questions.each_with_index do |question, index| %>
        <% active_number += 1 if question.active? %>
        <%= render "moderate/questions/item", question: question, number: question.active? ? active_number : "—", first: index.zero?, last: index == @questions.size - 1 %>
      <% end %>
    </ol>
  <% end %>
</section>
----app/views/moderate/questions/_item.html.erb
<li id="<%= dom_id(question) %>" class="card question-item <%= 'question-item--inactive' unless question.active? %>">
  <div class="question-item__num"><%= number %></div>
  <div>
    <div class="question-item__body"><%= question.body %></div>
    <ul class="question-item__options">
      <% question.options.each_with_index do |option, index| %>
        <li class="<%= 'is-correct' if option['correct'] %>"><%= option_letter(index) %>. <%= option['text'] %><% if option['correct'] %><span class="visually-hidden"> (correct)</span><% end %></li>
      <% end %>
    </ul>
  </div>
  <div class="question-item__actions">
    <div class="buttons">
      <%= button_to "↑", move_up_moderate_quiz_question_path(@quiz, question), method: :patch, class: "btn btn--ghost btn--icon", aria: { label: "Move up" }, title: "Move up", disabled: first %>
      <%= button_to "↓", move_down_moderate_quiz_question_path(@quiz, question), method: :patch, class: "btn btn--ghost btn--icon", aria: { label: "Move down" }, title: "Move down", disabled: last %>
    </div>
    <%= form_with model: question, url: activation_moderate_quiz_question_path(@quiz, question), namespace: dom_id(question) do |form| %>
      <%= form.label :active, class: "checkbox" do %><%= form.check_box :active, data: { autosubmit: true } %> Active<% end %>
    <% end %>
    <div class="buttons">
      <%= link_to "Edit", edit_moderate_quiz_question_path(@quiz, question), class: "btn btn--sm" %>
      <%= button_to "Delete", moderate_quiz_question_path(@quiz, question), method: :delete, class: "btn btn--sm btn--danger", form: { data: { confirm: "Delete this question?" } } %>
    </div>
  </div>
</li>
